/* Written by context-ds from its brand files. Do not edit; run the CLI again to update. */
:root {
	/* Core */
	--ds-color-brand: #2563EB;
	--ds-color-black: #000000;
	--ds-color-white: #FFFFFF;
	--ds-color-blue-10: #E9EFFD;
	--ds-color-blue-20: #D3E0FB;
	--ds-color-blue-40: #A8C1F7;
	--ds-color-blue-60: #7CA1F3;
	--ds-color-blue-80: #5182EF;
	--ds-color-blue-90: #3B73ED;
	--ds-color-navy-30: #0B1E46;
	--ds-color-neutral-5: #F8F8F8;
	--ds-color-neutral-10: #E6E6E6;
	--ds-color-neutral-20: #CCCCCC;
	--ds-color-neutral-40: #999999;
	--ds-color-neutral-60: #666666;
	--ds-color-neutral-70: #4D4D4D;
	--ds-color-neutral-80: #333333;
	--ds-color-neutral-90: #191919;

	/* Surfaces: white, blue or black, never a gray page */
	--ds-color-bg-default: #FFFFFF;
	--ds-color-bg-subtle: #F8F8F8;
	--ds-color-bg-frame: #F2F2F2;
	--ds-color-bg-canvas: #FAFAFA;
	--ds-color-bg-tint: #E9EFFD;
	--ds-color-bg-brand: #2563EB;
	--ds-color-bg-inverse: #000000;
	--ds-color-bg-dark: #1A1A1A;
	--ds-color-bg-code: #0D1117;
	--ds-color-bg-scrim: rgb(0 0 0 / 0.1);
	--ds-color-bg-announcement: #F7F8FA;

	/* Text: black, and black at 65, 60, 55 and 40 percent on white */
	--ds-color-text-default: #000000;
	--ds-color-text-secondary: #595959;
	--ds-color-text-muted: #666666;
	--ds-color-text-subtle: #737373;
	--ds-color-text-nav: #4D4D4D;
	--ds-color-text-faint: #999999;
	--ds-color-text-inverse: #FFFFFF;
	--ds-color-text-brand: #2563EB;
	--ds-color-text-on-brand: #FFFFFF;

	/* Lines */
	--ds-color-border-default: #E6E6E6;
	--ds-color-border-subtle: #F0F0F0;
	--ds-color-border-strong: #CCCCCC;
	--ds-color-border-hairline: rgb(0 0 0 / 0.08);
	--ds-color-border-rule: #E5E7EB;
	--ds-color-border-node: #D1D5DC;
	--ds-color-border-brand: #2563EB;
	--ds-color-border-on-brand: #FFFFFF;
	--ds-color-ring-tint: rgb(37 99 235 / 0.1);
	--ds-color-ring-on-brand: rgb(255 255 255 / 0.3);
	--ds-color-wash-hover: rgb(0 0 0 / 0.04);
	--ds-color-wash-pill: rgb(0 0 0 / 0.06);
	--ds-color-wash-selected: rgb(0 0 0 / 0.07);

	/* Actions and states */
	--ds-color-action-primary: #000000;
	--ds-color-action-primary-hover: #333333;
	--ds-color-action-primary-fg: #FFFFFF;
	--ds-color-status-success: #15803D;
	--ds-color-status-warning: #B45309;
	--ds-color-status-danger: #DC2626;
	--ds-color-focus-ring: #2563EB;
	--ds-color-chart-series-1: #3B82F6;
	--ds-color-chart-series-2: #14B8A6;
	--ds-color-chart-series-3: #F59E0B;
	--ds-color-chart-series-4: #8B5CF6;
	/* The three dots of a code window's title bar. */
	--ds-color-window-close: #FF5F56;
	--ds-color-window-minimize: #FFBD2E;
	--ds-color-window-zoom: #27C93F;
	/* From the dashboard redesign (brand-dev-webapp PR 1045, dashboard-system.css): the full ramps, alerts, the
	   HTTP status chart colors and the skeleton sheen. */
	--ds-color-blue-30: #BED0F9;
	--ds-color-blue-50: #92B1F5;
	--ds-color-blue-70: #6692F1;
	--ds-color-navy-20: #07142F;
	--ds-color-navy-60: #163B8D;
	--ds-color-neutral-30: #B2B2B2;
	--ds-color-neutral-50: #808080;
	--ds-color-alert-strong: #E5484D;
	--ds-color-alert: #F0868A;
	--ds-color-alert-soft: #F7C0C2;
	--ds-color-chart-ok: #22C55E;
	--ds-color-chart-client-error: #F59E0B;
	--ds-color-chart-server-error: #F97316;
	--ds-color-chart-200: #22C55E;
	--ds-color-chart-202: #10B981;
	--ds-color-chart-400: #F59E0B;
	--ds-color-chart-401: #EF4444;
	--ds-color-chart-402: #EC4899;
	--ds-color-chart-404: #F97316;
	--ds-color-chart-409: #EAB308;
	--ds-color-chart-rate-limited: #9A7FE0;
	--ds-color-skeleton-shine: #EDEDED;

	/* Type */
	--ds-font-sans: var(--font-rethink-sans, "Rethink Sans"), system-ui, sans-serif;
	--ds-font-data: var(--font-doto, "Doto"), ui-monospace, monospace;
	--ds-font-mono: var(--font-ibm-plex-mono, "IBM Plex Mono"), ui-monospace, monospace;
	--ds-font-weight-regular: 400;
	--ds-font-weight-medium: 500;
	--ds-text-hero: clamp(2.5rem, 1.75rem + 2.5vw, 3.875rem);
	--ds-text-h1: 3.5rem;
	--ds-text-h2: 2.75rem;
	--ds-text-h3: 2rem;
	--ds-text-h4: 1.5rem;
	--ds-text-h5: 1.25rem;
	--ds-text-body-lg: 1.125rem;
	--ds-text-body: 1rem;
	--ds-text-body-sm: 0.875rem;
	--ds-text-caption: 0.75rem;
	/* Chart axis labels (the product's charts). */
	--ds-text-axis: 11px;
	--ds-leading-tight: 1.1;
	--ds-leading-heading: 1.2;
	--ds-leading-snug: 1.3;
	--ds-leading-relaxed: 1.625;
	/* Section headings on the site, and code in a window. */
	--ds-leading-display: 1.12;
	--ds-leading-code: 1.7;
	--ds-tracking-tight: -0.035em;
	--ds-tracking-normal: 0;

	/* Space (rem, so it follows the root) */
	--ds-space-0: 0;
	--ds-space-px: 1px;
	--ds-space-0-5: 0.125rem;
	--ds-space-1: 0.25rem;
	--ds-space-1-5: 0.375rem;
	--ds-space-2: 0.5rem;
	--ds-space-2-5: 0.625rem;
	--ds-space-3: 0.75rem;
	--ds-space-3-5: 0.875rem;
	--ds-space-4: 1rem;
	--ds-space-5: 1.25rem;
	--ds-space-6: 1.5rem;
	--ds-space-7: 1.75rem;
	--ds-space-8: 2rem;
	--ds-space-9: 2.25rem;
	--ds-space-10: 2.5rem;
	--ds-space-12: 3rem;
	--ds-space-14: 3.5rem;
	--ds-space-16: 4rem;
	--ds-space-20: 5rem;
	--ds-space-24: 6rem;
	--ds-space-32: 8rem;

	/* Layout */
	--ds-layout-column: 68.75rem;
	--ds-layout-column-wide: 81.25rem;
	/* The ruled column's width: full width on phones, 90vw, then min(85vw, column-wide) (site.css). Content containers use it. */
	--ds-frame-column: calc(100% - 2px);
	--ds-layout-text: 36rem;
	--ds-layout-heading: 42rem;

	/* Shape */
	--ds-radius-sm: 0.25rem;
	--ds-radius-control: 0.5rem;
	--ds-radius-card: 0.5rem;
	--ds-radius-shell: 0.75rem;
	--ds-radius-panel: 2.5rem;
	--ds-radius-pill: 9999px;
	--ds-shadow-card: 0 0 0 1px var(--ds-color-border-hairline);
	--ds-shadow-raised: 0 0.25rem 0.5rem rgb(41 41 41 / 0.06), 0 0.125rem 0.25rem rgb(41 41 41 / 0.04), 0 0 0 1px rgb(41 41 41 / 0.08);
	--ds-shadow-floating: 0 0 0 1px rgb(0 0 0 / 0.06), 0 0.5rem 1.5rem -0.5rem rgb(0 0 0 / 0.12);
	--ds-shadow-key: 0 1px 2px rgb(0 0 0 / 0.16);
	--ds-shadow-tooltip: 0 0 0 1px var(--ds-color-border-hairline), 0 4px 12px rgb(0 0 0 / 0.08);
	--ds-shadow-ring-hover: 0 0 0 4px var(--ds-color-ring-tint);

	/* Motion: fast UI feedback only, no ease-in */
	--ds-duration-fast: 150ms;
	--ds-duration-base: 200ms;
	--ds-duration-moderate: 250ms;
	--ds-duration-slow: 300ms;
	--ds-easing-out: cubic-bezier(0.22, 1, 0.36, 1);
	--ds-easing-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}

.ds-product {
	--ds-color-bg-default: #FFFFFF;
	--ds-color-text-muted: #4D4D4D;
	--ds-color-text-subtle: #707070;
	--ds-color-border-hairline: rgb(0 0 0 / 0.06);
	--ds-text-display: 56px;
	--ds-text-h3: 28px;
	--ds-text-h4: 21px;
	--ds-text-h5: 18px;
	--ds-text-body-lg: 16px;
	--ds-text-body: 15px;
	--ds-text-body-sm: 12.6px;
	--ds-text-caption: 12px;
	--ds-radius-control: 7.5px;
	--ds-radius-card: 10px;
	--ds-radius-shell: 12px;
	--ds-shadow-card: 0 0 0 1px var(--ds-color-border-hairline), 0 1px 1px rgb(0 0 0 / 0.05), 0 2px 4px rgb(0 0 0 / 0.06), 0 4px 14px -4px rgb(0 0 0 / 0.1);
	--ds-shadow-floating: 0 0 0 1px var(--ds-color-border-hairline), 0 0.5rem 1.5rem -0.5rem rgb(0 0 0 / 0.16);
}

:is(.dark, [data-theme="dark"]) .ds-product,
